"""
Base strategy interface. All strategies must implement this.
"""

from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Dict, List, Optional
import pandas as pd


@dataclass
class Signal:
    """A signal generated by a strategy for a single stock."""
    symbol: str
    score: float            # Composite score (higher = more attractive)
    direction: int          # +1 long, -1 short, 0 neutral
    suggested_weight: float # Suggested portfolio weight (0.0 to 1.0)
    reason: str = ""
    metadata: dict = field(default_factory=dict)


class BaseStrategy(ABC):
    """Abstract base class for all strategies."""

    def __init__(self, name: str, config: dict):
        self.name = name
        self.config = config

    @abstractmethod
    def generate_signals(self, universe: List[str], prices: pd.DataFrame,
                         fundamentals: Dict[str, dict]) -> List[Signal]:
        """
        Given price history and fundamentals, return a ranked list of signals.

        Args:
            universe: List of ticker symbols to evaluate
            prices: DataFrame of daily closing prices (index=date, cols=symbols)
            fundamentals: Dict {symbol: {pe, pb, roe, revenue_growth, ...}}

        Returns:
            List of Signal objects sorted by score descending
        """
        pass

    def _normalize(self, series: pd.Series) -> pd.Series:
        """Normalize a series to [0, 1] range."""
        mn, mx = series.min(), series.max()
        if mx == mn:
            return pd.Series(0.5, index=series.index)
        return (series - mn) / (mx - mn)

    def _rank_normalize(self, series: pd.Series) -> pd.Series:
        """Rank-normalize series to [0, 1] using percentile ranks."""
        return series.rank(pct=True)
